import{_ as t,o as d,c as o,ai as c}from"./chunks/framework.jD4ETUAz.js";const u=JSON.parse('{"title":"工具与配置参考","description":"cninfo-mcp 全部 8 个 MCP 工具的参数说明：证券查找、定期报告与招股书、公告检索、文档阅读、财务与股东数据、PDF 下载，以及公告分类、数据集和环境变量配置。","frontmatter":{"title":"工具与配置参考","description":"cninfo-mcp 全部 8 个 MCP 工具的参数说明：证券查找、定期报告与招股书、公告检索、文档阅读、财务与股东数据、PDF 下载，以及公告分类、数据集和环境变量配置。","lastUpdated":"2026-11-15T21:29:49.000Z","upstream":"docs/tools.md","translation":"en/reference/tools.md","head":[["link",{"rel":"canonical","href":"https://youhaozhao.github.io/cninfo-mcp/reference/tools"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"cninfo-mcp"}],["meta",{"property":"og:title","content":"工具与配置参考 | cninfo-mcp"}],["meta",{"property":"og:description","content":"cninfo-mcp 全部 8 个 MCP 工具的参数说明：证券查找、定期报告与招股书、公告检索、文档阅读、财务与股东数据、PDF 下载，以及公告分类、数据集和环境变量配置。"}],["meta",{"property":"og:url","content":"https://youhaozhao.github.io/cninfo-mcp/reference/tools"}],["meta",{"property":"og:image","content":"https://youhaozhao.github.io/cninfo-mcp/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"工具与配置参考 | cninfo-mcp"}],["meta",{"name":"twitter:description","content":"cninfo-mcp 全部 8 个 MCP 工具的参数说明：证券查找、定期报告与招股书、公告检索、文档阅读、财务与股东数据、PDF 下载，以及公告分类、数据集和环境变量配置。"}],["meta",{"name":"twitter:image","content":"https://youhaozhao.github.io/cninfo-mcp/og.png"}],["link",{"rel":"alternate","hreflang":"zh","href":"https://youhaozhao.github.io/cninfo-mcp/reference/tools"}],["link",{"rel":"alternate","hreflang":"en","href":"https://youhaozhao.github.io/cninfo-mcp/en/reference/tools"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://youhaozhao.github.io/cninfo-mcp/en/reference/tools"}],["meta",{"property":"og:locale:alternate","content":"en_US"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"首页\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"参考\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/reference/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"工具与配置参考\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/reference/tools\\"}]}]}"]]},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1794778189000}'),a={name:"reference/tools.md"};function i(r,e,n,l,s,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="工具与配置参考" tabindex="-1">工具与配置参考 <a class="header-anchor" href="#工具与配置参考" aria-label="Permalink to &quot;工具与配置参考&quot;">​</a></h1><p>所有 <code>stock</code> 参数都接受代码或简称：<code>600519</code>、<code>000001.SZ</code>、<code>sh600519</code>、<code>920185</code>（北交所新旧代码均可）、<code>00700.HK</code>、<code>贵州茅台</code>。</p><h2 id="查找与检索" tabindex="-1">查找与检索 <a class="header-anchor" href="#查找与检索" aria-label="Permalink to &quot;查找与检索&quot;">​</a></h2><h3 id="search-securities" tabindex="-1"><code>search_securities</code> <a class="header-anchor" href="#search-securities" aria-label="Permalink to &quot;`search_securities`&quot;">​</a></h3><p>按代码、简称或拼音首字母查找证券。覆盖沪、深、北交所的 A 股和 B 股以及港股；基金和债券可按完整代码查到。</p><ul><li><code>query</code>（必填）：代码、简称片段或拼音首字母，如 <code>茅台</code>、<code>gzmt</code>、<code>6005</code></li><li><code>limit</code>（可选）：返回条数，默认 10</li></ul><h3 id="list-reports" tabindex="-1"><code>list_reports</code> <a class="header-anchor" href="#list-reports" aria-label="Permalink to &quot;`list_reports`&quot;">​</a></h3><p>列出一家公司的定期报告或招股书。</p><ul><li><code>stock</code>（必填）</li><li><code>report_type</code>（可选）：报告类型，默认 <code>annual</code></li><li><code>year</code>（可选）：报告期年份；招股书按披露年份。省略则返回全部年份</li><li><code>include_variants</code>（可选）：是否同时返回摘要、英文版等变体，默认 <code>false</code></li></ul><p><code>report_type</code> 的取值（中文别名如“年报”“半年报”也可以）：</p><table tabindex="0"><thead><tr><th>取值</th><th>报告</th></tr></thead><tbody><tr><td><code>annual</code></td><td>年度报告</td></tr><tr><td><code>semiannual</code></td><td>半年度报告（中报）</td></tr><tr><td><code>q1</code></td><td>第一季度报告</td></tr><tr><td><code>q3</code></td><td>第三季度报告</td></tr><tr><td><code>prospectus</code></td><td>招股说明书 / 招股意向书</td></tr></tbody></table><p>每条结果带 <code>kind</code> 字段：</p><table tabindex="0"><thead><tr><th><code>kind</code></th><th>含义</th><th>默认返回</th></tr></thead><tbody><tr><td><code>main</code></td><td>报告全文</td><td>是</td></tr><tr><td><code>revised</code></td><td>更新后 / 修订后的全文</td><td>是</td></tr><tr><td><code>summary</code></td><td>摘要（含深市季报的“正文”简版）</td><td>否</td></tr><tr><td><code>english</code></td><td>英文版</td><td>否</td></tr><tr><td><code>h_share</code></td><td>两地上市公司按港股规则编制的版本</td><td>否</td></tr><tr><td><code>other</code></td><td>已取消等其他情况</td><td>否</td></tr></tbody></table><p>“关于年报的更正公告”这类并非报告本身的公告不会出现在结果里。</p><h3 id="search-announcements" tabindex="-1"><code>search_announcements</code> <a class="header-anchor" href="#search-announcements" aria-label="Permalink to &quot;`search_announcements`&quot;">​</a></h3><p>检索公告，默认按披露时间从新到旧。</p><ul><li><code>stock</code>（可选）：代码或简称，多个用逗号分隔（最多 10 个）。省略即全市场检索</li><li><code>keyword</code>（可选）：标题关键字，如 <code>回购</code></li><li><code>categories</code>（可选）：公告分类，见下表，中英文名均可</li><li><code>start_date</code> / <code>end_date</code>（可选）：<code>YYYY-MM-DD</code>，北京时间，含首尾</li><li><code>market</code>（可选）：全市场检索时的板块筛选——<code>sh</code> 沪市、<code>shmb</code> 沪主板、<code>shkcp</code> 科创板、<code>sz</code> 深市、<code>szmb</code> 深主板、<code>szcy</code> 创业板、<code>bj</code> 北交所</li><li><code>source</code>（可选）：<code>announcements</code>（默认）或 <code>investor_relations</code>（调研 / 投资者关系活动记录）</li><li><code>sort</code>（可选）：<code>newest</code>（默认）或 <code>oldest</code></li><li><code>limit</code>（可选）：默认 30，最大 200</li><li><code>offset</code>（可选）：翻页位置</li></ul><p>返回 <code>total</code>（命中总数）；还有更多结果时带 <code>next_offset</code>，把它作为下一次调用的 <code>offset</code>。</p><p>公告分类：</p><table tabindex="0"><thead><tr><th>名称</th><th>分类</th><th>名称</th><th>分类</th></tr></thead><tbody><tr><td><code>annual_report</code></td><td>年报</td><td><code>equity_incentive</code></td><td>股权激励</td></tr><tr><td><code>semiannual_report</code></td><td>半年报</td><td><code>rights_issue</code></td><td>配股</td></tr><tr><td><code>q1_report</code></td><td>一季报</td><td><code>unlock</code></td><td>解禁</td></tr><tr><td><code>q3_report</code></td><td>三季报</td><td><code>corporate_bond</code></td><td>公司债</td></tr><tr><td><code>earnings_forecast</code></td><td>业绩预告</td><td><code>convertible_bond</code></td><td>可转债</td></tr><tr><td><code>dividend</code></td><td>权益分派</td><td><code>other_financing</code></td><td>其他融资</td></tr><tr><td><code>board</code></td><td>董事会</td><td><code>equity_change</code></td><td>股权变动</td></tr><tr><td><code>supervisory_board</code></td><td>监事会</td><td><code>correction</code></td><td>补充更正</td></tr><tr><td><code>shareholder_meeting</code></td><td>股东会</td><td><code>clarification</code></td><td>澄清致歉</td></tr><tr><td><code>operations</code></td><td>日常经营</td><td><code>risk_warning</code></td><td>风险提示</td></tr><tr><td><code>governance</code></td><td>公司治理</td><td><code>st_delisting</code></td><td>特别处理和退市</td></tr><tr><td><code>intermediary</code></td><td>中介报告</td><td><code>delisting_period</code></td><td>退市整理期</td></tr><tr><td><code>ipo</code></td><td>首发</td><td><code>placement</code></td><td>增发</td></tr></tbody></table><p><code>source=investor_relations</code> 时的分类：<code>research</code> 调研活动、<code>roadshow</code> 路演活动、<code>media_interview</code> 媒体采访、<code>ir_policy</code> 管理制度。</p><p>分类只适用于沪、深、北交所；港股公告请用 <code>keyword</code> 检索。</p><h2 id="阅读" tabindex="-1">阅读 <a class="header-anchor" href="#阅读" aria-label="Permalink to &quot;阅读&quot;">​</a></h2><h3 id="read-document" tabindex="-1"><code>read_document</code> <a class="header-anchor" href="#read-document" aria-label="Permalink to &quot;`read_document`&quot;">​</a></h3><p>阅读公告或报告正文（PDF；早期公告为 HTML）。结果是纯文本。</p><ul><li><code>url</code>（必填）：<code>list_reports</code> 或 <code>search_announcements</code> 返回的文档地址</li><li><code>pages</code>（可选）：页码范围，如 <code>5</code>、<code>10-20</code>、<code>1-3,8</code></li><li><code>query</code>（可选）：要在文档内定位的关键字，空格分隔，任一命中即可</li><li><code>max_chars</code>（可选）：输出字数上限，默认 20000</li></ul><p>三种用法：</p><ol><li>只给 <code>url</code>：返回页数、目录和开头几页。</li><li>给 <code>query</code>：返回命中的页码和上下文片段，用来在长报告里定位章节。</li><li>给 <code>pages</code>：返回这些页的全文。超出 <code>max_chars</code> 时，结果末尾会给出继续读取用的 <code>pages</code> 值。</li></ol><h2 id="结构化数据" tabindex="-1">结构化数据 <a class="header-anchor" href="#结构化数据" aria-label="Permalink to &quot;结构化数据&quot;">​</a></h2><p>仅支持沪、深、北交所上市公司。</p><h3 id="get-financials" tabindex="-1"><code>get_financials</code> <a class="header-anchor" href="#get-financials" aria-label="Permalink to &quot;`get_financials`&quot;">​</a></h3><ul><li><code>stock</code>（必填）</li><li><code>statements</code>（可选）：<code>indicators</code> 主要指标、<code>income</code> 利润表、<code>balance</code> 资产负债表、<code>cashflow</code> 现金流量表，可多选，默认 <code>indicators</code></li><li><code>period</code>（可选）：<code>annual</code>（默认）、<code>semiannual</code>、<code>q1</code>、<code>q3</code>；季报和半年报为年初至报告期末的累计值</li><li><code>periods</code>（可选）：返回最近几期，默认 5（上游最多提供 5 期）</li></ul><p>报表金额单位为万元，是巨潮个股页的精简口径（主要科目）；需要完整科目请用 <code>read_document</code> 读报告原文。</p><h3 id="get-company-data" tabindex="-1"><code>get_company_data</code> <a class="header-anchor" href="#get-company-data" aria-label="Permalink to &quot;`get_company_data`&quot;">​</a></h3><ul><li><code>stock</code>（必填）</li><li><code>datasets</code>（必填）：一次可取多个数据集（最多 8 个），并发获取</li><li><code>limit</code>（可选）：每个数据集返回的行数，默认 20</li></ul><table tabindex="0"><thead><tr><th>数据集</th><th>内容</th><th>数据集</th><th>内容</th></tr></thead><tbody><tr><td><code>profile</code></td><td>公司概况</td><td><code>unlocks</code></td><td>限售解禁</td></tr><tr><td><code>executives</code></td><td>高管与董监事</td><td><code>pledges</code></td><td>股权质押</td></tr><tr><td><code>dividends</code></td><td>历史分红</td><td><code>margin_trading</code></td><td>融资融券</td></tr><tr><td><code>share_structure</code></td><td>股本结构</td><td><code>block_trades</code></td><td>大宗交易</td></tr><tr><td><code>shareholder_count</code></td><td>股东人数</td><td><code>shareholder_trades</code></td><td>股东增减持</td></tr><tr><td><code>top_shareholders</code></td><td>十大股东</td><td><code>executive_trades</code></td><td>董监高持股变动</td></tr><tr><td><code>top_float_shareholders</code></td><td>十大流通股东</td><td><code>dragon_tiger</code></td><td>龙虎榜</td></tr><tr><td><code>fund_holdings</code></td><td>基金持股</td><td></td><td></td></tr></tbody></table><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><h3 id="download-reports" tabindex="-1"><code>download_reports</code> <a class="header-anchor" href="#download-reports" aria-label="Permalink to &quot;`download_reports`&quot;">​</a></h3><p>把定期报告或招股书的 PDF 保存到下载目录，选取规则与 <code>list_reports</code> 相同（只下载报告全文）。</p><ul><li><code>stock</code>（必填）</li><li><code>report_type</code>（可选）：默认 <code>annual</code></li><li><code>year</code>（可选）：省略则下载全部年份</li><li><code>save_path</code>（可选）：下载根目录下的子目录，如 <code>annual/2024</code>；根目录之外的路径会被拒绝</li></ul><h3 id="download-documents" tabindex="-1"><code>download_documents</code> <a class="header-anchor" href="#download-documents" aria-label="Permalink to &quot;`download_documents`&quot;">​</a></h3><ul><li><code>urls</code>（必填）：文档地址列表（最多 50 个）</li><li><code>save_path</code>（可选）：同上</li></ul><p>文件名为 <code>代码_简称_标题_公告ID.pdf</code>。目标文件已存在时不会重新下载；每个文件独立处理，失败的在 <code>failures</code> 里逐条列出。</p><h2 id="提示词模板" tabindex="-1">提示词模板 <a class="header-anchor" href="#提示词模板" aria-label="Permalink to &quot;提示词模板&quot;">​</a></h2><ul><li><code>company_research</code>：上市公司深度研究</li><li><code>earnings_review</code>：最新财报解读</li></ul><h2 id="结果完整性" tabindex="-1">结果完整性 <a class="header-anchor" href="#结果完整性" aria-label="Permalink to &quot;结果完整性&quot;">​</a></h2><p>涉及多次上游请求的结果都带 <code>complete</code> 字段。部分分页、部分数据集或部分文件失败时，已取得的内容照常返回，同时 <code>complete</code> 为 <code>false</code> 并附带 <code>warnings</code> / <code>errors</code>。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>全部通过环境变量设置，都可以省略：</p><table tabindex="0"><thead><tr><th>环境变量</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>CNINFO_MCP_DOWNLOAD_DIR</code></td><td>下载根目录，下载工具只能写入这个目录</td><td><code>~/Downloads/cninfo-mcp</code></td></tr><tr><td><code>CNINFO_MCP_CACHE_DIR</code></td><td>证券列表、已读取文档及其文本的缓存目录</td><td>系统缓存目录下的 <code>cninfo-mcp</code></td></tr><tr><td><code>CNINFO_MCP_CACHE_MAX_MB</code></td><td>文档缓存上限，超出后淘汰最久未使用的文件</td><td><code>1024</code></td></tr><tr><td><code>CNINFO_MCP_CONCURRENCY</code></td><td>同时向巨潮发起的请求数（1–8）</td><td><code>4</code></td></tr><tr><td><code>CNINFO_MCP_TIMEOUT_MS</code></td><td>单次请求超时（毫秒）</td><td><code>30000</code></td></tr><tr><td><code>CNINFO_MCP_DEBUG</code></td><td>设为 <code>1</code> 时在 stderr 打印上游请求、重试与限流</td><td>未设置</td></tr></tbody></table><p>命令行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @youhaozhao/cninfo-mcp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 启动 MCP 服务器（stdio）</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @youhaozhao/cninfo-mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> probe</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 联网自检：公告查询、财务数据、文档读取</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @youhaozhao/cninfo-mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> selftest</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 离线自检：安装本身（PDF 文本提取）是否可用</span></span></code></pre></div><h2 id="数据范围与限制" tabindex="-1">数据范围与限制 <a class="header-anchor" href="#数据范围与限制" aria-label="Permalink to &quot;数据范围与限制&quot;">​</a></h2><ul><li>公告检索：沪、深、北交所上市公司（含 B 股），以及港股公告；基金、债券可按代码检索公告。</li><li><code>list_reports</code>、<code>get_financials</code>、<code>get_company_data</code>：沪、深、北交所上市公司。</li><li>公告按标题关键字检索，不支持跨公告的全文检索；读取单个文档时可以在文档内按关键字定位。</li><li>扫描件（部分早期公告）没有文本层，无法读出正文。</li><li>不提供实时行情和 K 线。</li></ul>',54)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
